#!/usr/bin/python3

import pyrob.core as rob
import random
from pyrob.tasks import check_filled_cells, find_cells_to_be_filled

# Порядок вариантов: один раз перемешиваем при загрузке модуля — без повторений в пределах 0..3
_variant_order = list(range(4))
random.shuffle(_variant_order)

class Task:
    CHECKS = 4

    def load_level(self, n):
        idx = _variant_order[n % len(_variant_order)]
        if idx == 0:
            rob.set_field_size(2, 2)
            rob.set_cell_type(1, 1, rob.CELL_TO_BE_FILLED)
            rob.set_parking_cell(1, 1)
            rob.goto(0, 0)
        elif idx == 1:
            rob.set_field_size(2, 2)
            rob.set_cell_type(1, 0, rob.CELL_TO_BE_FILLED)
            rob.set_parking_cell(1, 0)
            rob.goto(0, 1)
        elif idx == 2:
            rob.set_field_size(2, 2)
            rob.set_cell_type(0, 0, rob.CELL_TO_BE_FILLED)
            rob.set_parking_cell(0, 0)
            rob.goto(1, 1)
        elif idx == 3:
            rob.set_field_size(2, 2)
            rob.set_cell_type(0, 1, rob.CELL_TO_BE_FILLED)
            rob.set_parking_cell(0, 1)
            rob.goto(1, 0)

        self.cells_to_fill = find_cells_to_be_filled()

    def check_solution(self):
        return check_filled_cells(self.cells_to_fill) and rob.is_parking_point()
